draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw stick figure (Rousseau) in natural state
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw tree (symbolizing natural state)
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 + 50, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 50, 30, 0, 2*Math.PI);
  ctx.stroke();

  // animate Rousseau moving towards social contract
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 50*Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 100 + 50*Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 50*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 80 + 50*Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 50*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 120 + 50*Math.sin(t), H/2 + 70);
  ctx.stroke();

  // draw social contract (book)
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 + 150, H/2 - 20, 50, 50);
  ctx.fillStyle = 'white';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('SC', W/2 + 175, H/2);

  ctx.restore();
}
